<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Storage};
use App\Models\{User,MarketingChannelConnection};
class MarketingImagePublishingTest extends TestCase {
 use RefreshDatabase;
 private function setupPost(){Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['marketing.post_queue_enabled'=>false,'marketing.post_scheduling_enabled'=>false,'app.url'=>'https://shop.example','services.facebook.client_id'=>'publish-test','services.facebook.client_secret'=>'test-secret','marketing.social_publishing_enabled'=>true,'marketing.execution_enabled'=>false]);Storage::fake('public');Storage::fake('local');$im=imagecreatetruecolor(50,50);ob_start();imagejpeg($im);Storage::disk('public')->put('test.jpg',ob_get_clean());imagedestroy($im);$product=\App\Models\Product::create(['title'=>'Publishing fixture','handle'=>'publishing-fixture','status'=>'active','base_price'=>25]);$image=\App\Models\ProductImage::create(['product_id'=>$product->id,'path'=>'test.jpg','position'=>0]);$accounts=[];foreach(['facebook','instagram'] as $platform)$accounts[]=MarketingChannelConnection::create(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>$platform,'provider_account_id'=>$platform==='facebook'?'123':'456','linked_page_id'=>$platform==='instagram'?'123':null,'app_id'=>'publish-test','name'=>$platform,'access_token'=>'PRIVATE-TOKEN','permissions'=>['pages_show_list','pages_read_engagement','pages_manage_posts','instagram_basic','instagram_content_publish'],'tasks'=>['CREATE_CONTENT'],'authorized_by'=>$u->id,'state'=>'connected']);return ['id'=>(string)\Illuminate\Support\Str::uuid(),'version'=>0,'title'=>'Publishing test','copy'=>'JW Marketing Studio publishing test. No offer or product claim.','targets'=>array_column(array_map(fn($a)=>$a->toArray(),$accounts),'id'),'copies'=>[],'asset'=>'image:'.$image->id,'type'=>'Post','tz'=>'Asia/Kuala_Lumpur'];}
 public function test_two_image_destinations_publish_once_and_keep_receipts(){ $p=$this->setupPost();Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1']),'*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::response(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'ig-post-1'])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertDontSee('PRIVATE-TOKEN');$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409);Http::assertSentCount(4);$this->assertDatabaseCount('marketing_post_attempts',2); }
 public function test_instagram_permalink_is_saved_without_exposing_credentials(){ $p=$this->setupPost();$p['targets']=[$p['targets'][1]];Http::fake(['*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::response(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'987654321']),'*/987654321*'=>Http::response(['permalink'=>'https://www.instagram.com/p/ABC123/'])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertJsonPath('post.outcomes.'.$p['targets'][0].'.url','https://www.instagram.com/p/ABC123/')->assertDontSee('PRIVATE-TOKEN');Http::assertSentCount(4); }
 public function test_permalink_lookup_failure_keeps_confirmed_success(){ $p=$this->setupPost();$p['targets']=[$p['targets'][1]];Http::fake(['*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::response(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'987654321']),'*/987654321*'=>Http::response(['error'=>['code'=>190]],400)]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertJsonPath('post.outcomes.'.$p['targets'][0].'.url',null);Http::assertSentCount(4); }
 public function test_existing_instagram_result_can_resolve_link_without_republishing(){ $p=$this->setupPost();$target=$p['targets'][1];$row=\App\Models\MarketingPost::create(['id'=>$p['id'],'user_id'=>auth()->id(),'merchant_key'=>app(\App\Services\Marketing\MarketingPosts::class)->merchant(),'status'=>'Published','version'=>2,'timezone'=>'Asia/Kuala_Lumpur','document'=>['targets'=>[$target],'outcomes'=>[$target=>['status'=>'Published','ref'=>'987654321']]]]);Http::fake(['*/987654321*'=>Http::response(['permalink'=>'https://www.instagram.com/p/OLD123/'])]);$this->postJson('/admin/marketing/posts/data/link',['id'=>$row->id,'version'=>2])->assertOk()->assertJsonPath('post.outcomes.'.$target.'.url','https://www.instagram.com/p/OLD123/');Http::assertSentCount(1);$this->assertDatabaseCount('marketing_post_attempts',0);$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->postJson('/admin/marketing/posts/data/link',['id'=>$row->id,'version'=>2])->assertNotFound();Http::assertSentCount(1); }
 public function test_facebook_multi_image_is_one_post_with_ordered_attachments(){ $p=$this->setupPost();$p['targets']=[$p['targets'][0]];$image=\App\Models\ProductImage::first();$second=\App\Models\ProductImage::create(['product_id'=>$image->product_id,'path'=>'test.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$second->id];$p['format']='carousel';$index=0;Http::fake(function($r)use(&$index){if(str_ends_with($r->url(),'/photos'))return Http::response(['id'=>'photo-'.++$index]);if(str_ends_with($r->url(),'/feed'))return Http::response(['id'=>'123_789']);return Http::response([],500);});$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published');Http::assertSentCount(3);Http::assertSent(fn($r)=>str_ends_with($r->url(),'/feed')&&json_decode($r['attached_media'],true)===[['media_fbid'=>'photo-1'],['media_fbid'=>'photo-2']]);$this->assertDatabaseCount('marketing_post_attempts',1); }
 public function test_instagram_carousel_retains_children_and_publishes_once(){ $p=$this->setupPost();$p['targets']=[$p['targets'][1]];$image=\App\Models\ProductImage::first();$other=\App\Models\ProductImage::create(['product_id'=>$image->product_id,'path'=>'test.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$other->id];$p['format']='carousel';$next=0;Http::fake(function($r)use(&$next){if(str_ends_with($r->url(),'/456/media'))return Http::response(['id'=>isset($r['media_type'])?'parent':'child'.++$next]);if($r->method()==='GET'&&str_contains($r->url(),'permalink'))return Http::response(['permalink'=>'https://www.instagram.com/p/CAROUSEL/']);if($r->method()==='GET')return Http::response(['status_code'=>'FINISHED']);if(str_ends_with($r->url(),'/media_publish'))return Http::response(['id'=>'987654321']);return Http::response([],500);});$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertJsonPath('post.outcomes.'.$p['targets'][0].'.url','https://www.instagram.com/p/CAROUSEL/');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();Http::assertSentCount(8);$this->assertDatabaseCount('marketing_post_attempts',1); }
 public function test_multi_image_uncertain_final_submit_never_repeats(){ $p=$this->setupPost();$p['targets']=[$p['targets'][0]];$image=\App\Models\ProductImage::first();$other=\App\Models\ProductImage::create(['product_id'=>$image->product_id,'path'=>'test.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$other->id];$p['format']='carousel';$n=0;$calls=0;Http::fake(function($r)use(&$n,&$calls){$calls++;if(str_ends_with($r->url(),'/photos'))return Http::response(['id'=>'photo'.++$n]);throw new \Illuminate\Http\Client\ConnectionException('timeout');});$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();$this->assertSame(3,$calls);$this->assertDatabaseCount('marketing_post_attempts',1); }
 public function test_tiktok_multi_image_preserves_order_in_one_submission(){ $p=$this->tiktokPhoto();$first=\App\Models\ProductImage::first();$second=\App\Models\ProductImage::create(['product_id'=>$first->product_id,'path'=>'test.jpg','position'=>1]);$p['assets']=[$p['asset'],'image:'.$second->id];$p['format']='carousel';Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true],'error'=>['code'=>'ok']]),'*/content/init/'=>Http::response(['data'=>['publish_id'=>'task-photos'],'error'=>['code'=>'ok']]),'*/status/fetch/'=>Http::response(['data'=>['status'=>'PUBLISH_COMPLETE','publicaly_available_post_id'=>['7123456789012345678']],'error'=>['code'=>'ok']])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published');Http::assertSent(fn($r)=>str_ends_with($r->url(),'/content/init/')&&count($r['source_info']['photo_images'])===2&&str_contains($r['source_info']['photo_images'][0],'index=0')&&str_contains($r['source_info']['photo_images'][1],'index=1'));Http::assertSentCount(3);$this->assertDatabaseCount('marketing_post_attempts',1); }
 public function test_private_uploaded_image_uses_image_adapter_not_catalog_lookup(){ $p=$this->setupPost();$p['targets']=[$p['targets'][0]];$a=$this->post('/admin/marketing/posts/upload',['file'=>\Illuminate\Http\UploadedFile::fake()->image('merchant.png',640,640)],['Accept'=>'application/json'])->assertOk()->json('asset');$p['asset']=$a['id'];$p['assets']=[$a['id']];$p['format']='image';Http::fake(['*/123/photos'=>Http::response(['id'=>'photo1']),'*/123/feed'=>Http::response(['id'=>'123_789'])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published');Http::assertSentCount(2); }
 public function test_unknown_submit_does_not_retry_or_duplicate_successful_target(){ $p=$this->setupPost();Http::fake(['*/123/photos'=>Http::response(['id'=>'photo-1','post_id'=>'123_post-1']),'*/456/media'=>Http::response(['error'=>['code'=>2,'message'=>'PRIVATE-TOKEN']],503)]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention')->assertDontSee('PRIVATE-TOKEN');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();Http::assertSentCount(2); }
 public function test_container_wait_uses_known_container_and_never_creates_another(){ $p=$this->setupPost();$p['targets']=[$p['targets'][1]];Http::fake(['*/456/media'=>Http::response(['id'=>'container-1']),'*/container-1*'=>Http::sequence()->push(['status_code'=>'IN_PROGRESS'])->push(['status_code'=>'FINISHED']),'*/456/media_publish'=>Http::response(['id'=>'ig-post-1'])]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Publishing');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk()->assertJsonPath('post.status','Published');Http::assertSentCount(4); }
 public function test_publishing_gate_stops_before_network_and_delivery_image_requires_signature(){ $p=$this->setupPost();config(['marketing.social_publishing_enabled'=>false]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(423);$this->get('/marketing/post-delivery/1')->assertForbidden();Http::assertNothingSent(); }

 private function tiktokPhoto():array { $p=$this->setupPost();\Illuminate\Support\Facades\URL::forceRootUrl('https://shop.example');\Illuminate\Support\Facades\URL::forceScheme('https');config(['services.tiktok.client_id'=>'tk','marketing.external_video_publishing_enabled'=>true,'marketing.tiktok_photo_verified_prefix'=>'https://shop.example/marketing/post-delivery/']);$a=MarketingChannelConnection::create(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>'tiktok','provider_account_id'=>'tk-photo','app_id'=>'tk','name'=>'Photo creator','access_token'=>'PRIVATE-TOKEN','permissions'=>['user.info.basic','video.publish'],'authorized_by'=>auth()->id(),'state'=>'connected','expires_at'=>now()->addHour()]);$p['targets']=[$a->id];$p['options']=[$a->id=>['privacy'=>'SELF_ONLY','allow_comment'=>false,'commercial'=>false,'your_brand'=>false,'branded'=>false,'terms'=>true,'synthetic'=>false,'auto_add_music'=>false]];return $p; }
 public function test_tiktok_photo_publishes_without_video_and_queries_existing_task_only(){ $p=$this->tiktokPhoto();Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true],'error'=>['code'=>'ok']]),'*/content/init/'=>Http::response(['data'=>['publish_id'=>'photo-task'],'error'=>['code'=>'ok']]),'*/status/fetch/'=>Http::sequence()->push(['data'=>['status'=>'PROCESSING_UPLOAD'],'error'=>['code'=>'ok']])->push(['data'=>['status'=>'PUBLISH_COMPLETE'],'error'=>['code'=>'ok']])]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Publishing');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk()->assertJsonPath('post.status','Published');Http::assertSent(fn($r)=>str_ends_with($r->url(),'/content/init/')&&$r['media_type']==='PHOTO'&&$r['post_mode']==='DIRECT_POST'&&$r['post_info']['privacy_level']==='SELF_ONLY'&&$r['source_info']['source']==='PULL_FROM_URL'&&count($r['source_info']['photo_images'])===1);Http::assertSentCount(4);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409); }
 public function test_tiktok_photo_missing_verified_domain_or_consent_stops_before_network(){ $p=$this->tiktokPhoto();config(['marketing.tiktok_photo_verified_prefix'=>'']);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertNothingSent();config(['marketing.tiktok_photo_verified_prefix'=>'https://shop.example/marketing/post-delivery/']);$p['options'][$p['targets'][0]]['terms']=false;$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertNothingSent(); }

 public function test_photo_unknown_init_is_not_repeated_and_draft_is_preserved(){ $p=$this->tiktokPhoto();Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true],'error'=>['code'=>'ok']]),'*/content/init/'=>Http::response(['error'=>['code'=>'internal_error']],503)]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();$p['version']=$r->json('post.version');$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409);Http::assertSentCount(2); }
 public function test_photo_domain_mismatch_and_creator_disabled_comments_are_rejected(){ $p=$this->tiktokPhoto();config(['marketing.tiktok_photo_verified_prefix'=>'https://another.example/']);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertNothingSent();config(['marketing.tiktok_photo_verified_prefix'=>'https://shop.example/marketing/post-delivery/']);$p['options'][$p['targets'][0]]['allow_comment']=true;Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true],'error'=>['code'=>'ok']])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertSentCount(1); }
 public function test_formats_are_shared_with_editor_and_youtube_image_is_blocked(){ $p=$this->tiktokPhoto();$this->getJson('/admin/marketing/posts/data')->assertOk()->assertJsonPath('formats.tiktok.Post.0','image')->assertJsonPath('formats.youtube.Reel.0','video')->assertJsonPath('tiktokPhotoReady',true);$a=MarketingChannelConnection::findOrFail($p['targets'][0]);config(['services.youtube.client_id'=>'yt']);$a->update(['platform'=>'youtube','app_id'=>'yt','permissions'=>['https://www.googleapis.com/auth/youtube.readonly','https://www.googleapis.com/auth/youtube.upload']]);$p['due']=now()->addDay()->toIso8601String();$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertUnprocessable();Http::assertNothingSent(); }
}
